import{_ as e,c as a,o,a4 as l}from"./chunks/framework.D5y910bP.js";const m=JSON.parse('{"title":"Cloudflare SaaS setup","description":"","frontmatter":{"date":"2025-01-21T00:00:00.000Z","tags":["cloudflare","saas","domain","proxy","cname"],"title":"Cloudflare SaaS setup"},"headers":[],"relativePath":"blog/cloudflare-saas-setup.md","filePath":"blog/cloudflare-saas-setup.md","lastUpdated":1752318390000}'),r={name:"blog/cloudflare-saas-setup.md"},t=l('<h1 id="cloudflare-saas-setup" tabindex="-1">Cloudflare SaaS setup <a class="header-anchor" href="#cloudflare-saas-setup" aria-label="Permalink to &quot;Cloudflare SaaS setup&quot;">​</a></h1><p>Setting up a Cloudflare zone for SaaS</p><blockquote><p><a href="https://developers.cloudflare.com/cloudflare-for-platforms/cloudflare-for-saas/start/getting-started/" target="_blank" rel="noreferrer">https://developers.cloudflare.com/cloudflare-for-platforms/cloudflare-for-saas/start/getting-started/</a></p></blockquote><ul><li>Add your zone to Cloudflare on a Free plan.</li><li>Enable Cloudflare for SaaS for your zone. <ul><li>Select your account and zone.</li><li>Go to SSL/TLS &gt; Custom Hostnames.</li><li>Select Enable.</li><li>Confirm Payment</li></ul></li><li>Review the Hostname prioritization guidelines. Wildcard custom hostnames behave differently than an exact hostname match. <ul><li><a href="https://developers.cloudflare.com/ssl/reference/certificate-and-hostname-priority/#hostname-priority" target="_blank" rel="noreferrer">https://developers.cloudflare.com/ssl/reference/certificate-and-hostname-priority/#hostname-priority</a></li></ul></li><li>Create fallback origin <ul><li>Create a proxied A, AAAA, or CNAME record pointing to the IP address of your fallback origin (where Cloudflare will send custom hostname traffic). <ul><li><code>A proxy-fallback &lt;origin-ip&gt; Proxied</code></li><li><code>AAAA proxy-fallback 100:: Proxied</code> (for worker)</li><li>or <code>A proxy-fallback 192.0.2.0 Proxied</code> (for worker)</li></ul></li><li>Designate that record as your fallback origin. <ul><li>Go to SSL/TLS &gt; Custom Hostnames.</li><li>For Fallback Origin, enter the hostname for your fallback origin.</li><li>Select Add Fallback Origin.</li><li>Once you have added the fallback origin, confirm that its status is Active.</li></ul></li><li>Workers as your fallback origin <ul><li>Ensure the fallback origin only has an originless DNS record (100:😃</li><li>In that same zone, navigate to Workers Routes.</li><li>Click Add route.</li><li>Decide whether you want traffic bound for your SaaS zone (example.com) to go to that Worker <ul><li><a href="https://developers.cloudflare.com/cloudflare-for-platforms/cloudflare-for-saas/start/advanced-settings/worker-as-origin/" target="_blank" rel="noreferrer">https://developers.cloudflare.com/cloudflare-for-platforms/cloudflare-for-saas/start/advanced-settings/worker-as-origin/</a></li><li>Worker routes have to be mapped to the custom hostname that are created later. For routing all to the same worker use <code>*/*</code> route, not the fallback origin as it doesn&#39;t work.</li></ul></li></ul></li></ul></li><li>(Optional) Create CNAME target <ul><li>Create a proxied CNAME that points your CNAME target to your fallback origin (can be a wildcard such as *.customers.saasprovider.com).</li><li><code>CNAME .customers proxy-fallback.saasprovider.com Proxied</code></li></ul></li></ul><h1 id="adding-hostnames" tabindex="-1">Adding hostnames <a class="header-anchor" href="#adding-hostnames" aria-label="Permalink to &quot;Adding hostnames&quot;">​</a></h1><ul><li>Docs are fine for this</li><li>Open website in cloudflare dashboard, SSL/TLS &gt; Custom Hostnames</li><li>Click Add Custom Hostname</li><li>Options - TLS 1.0 (default), HTTP Validation(might have downtime), cert by cloudflare</li></ul><h1 id="apex-domain-proxy" tabindex="-1">Apex domain proxy <a class="header-anchor" href="#apex-domain-proxy" aria-label="Permalink to &quot;Apex domain proxy&quot;">​</a></h1><ul><li>Customers can add CNAME record to point to our CNAME target, but many providers don&#39;t allow CNAME at apex domain. <ul><li>One solution is to either ask them to put nameservers for cloudflare and use it for DNS(since it does CNAME flatenning)</li><li>Or get cloudflare enterprise plan to get IP ranges or use BYOIP which also requires enterprise.</li><li>Or ask them to map www to our CNAME target and redirect apex to www.</li></ul></li></ul>',8),i=[t];function s(n,d,c,u,f,p){return o(),a("div",null,i)}const g=e(r,[["render",s]]);export{m as __pageData,g as default};
